commands.command:
/bin/zsh -lc python - <<'PY'
from more_itertools import numeric_range
from itertools import islice
import random
rng=random.Random(4); tested=0
for exponent in range(52,63):
 for sign in [-1,1]:
  for offset in range(-7,8):
   start=sign*(2**exponent+offset)
   for step in [-1.,1.,-1,1]:
    for stop in [start+int(step)*20,float(start+int(step)*20)]:
     r=numeric_range(start,stop,step)
     xs=list(islice(iter(r),10000))
     if len(xs)==10000: continue
     assert len(r)==len(xs),(start,stop,step,len(r),len(xs))
     for x in set(xs):assert x in r and r.index(x)==xs.index(x),(start,stop,step,x,r.index(x),xs.index(x))
     for x in [start,stop,start+.5*step]:
      assert (x in r)==(x in xs),(start,stop,step,x)
     tested+=1
print('PASS mixed float/int cases',tested)
PY

